with remaining_keys as (select customer_id from subscriptions except all select customer_id from subscriptions where year(start_date) >= 2024), kept_rows as (select s.* from subscriptions s inner join remaining_keys k on s.customer_id = k.customer_id) select plan, start_date, end_date, monthly_fee, status, case when status rlike '^(CANCELLED|EXPIRED)$' then 'GROUP_B' when status rlike '^(ACTIVE|PAUSED)$' then 'GROUP_A' else 'CORE' end as status_zone from kept_rows order by end_date nulls first;
